   [3]={next_id=4, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="数日过后。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [4]={next_id=5, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大空洞的纷乱渐渐沉淀下来。往日紧绷到窒息的压抑氛围，终于有了一丝松动。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [5]={next_id=6, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大家自发清理破损的房屋、规整杂乱的街道，搭建临时住所。久而久之，一处崭新的聚居地，在满目疮痍的弗亚矿区悄然成型。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [6]={next_id=7, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="微风裹挟着矿石独有的清冷气息，掠过聚居地错落的低矮木屋，一切都在朝着安稳与新生缓缓靠拢。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [7]={next_id=8, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你正靠在街边的石栏旁，看着来往忙碌、眉眼渐渐舒展的居民。这时，身后传来一阵轻盈脚步声。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [8]={next_id=9, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大空洞的居民，远比我们想象的要坚韧。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [9]={next_id=10, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是啊，生命的不屈就在于他们会不断适应并战胜困难。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [10]={next_id=11, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="动乱彻底平息之后，我原本以为这片人人谈之色变的矿区，会彻底沦为无人问津的死域。现在看来，是我低估了底层居民的韧性。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [11]={next_id=12, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="相比于那些盘踞在高楼里、养尊处优的家族掌权者，这些挣扎在生存线上的普通人，往往比任何人都要顽强。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [12]={next_id=13, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她从袖口抽出一份文件，递到你面前。纸张是烫金压边的，带着拉蒂夫家族特有的考究质感。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [13]={next_id=14, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这是？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [14]={next_id=15, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="合作协议。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [15]={next_id=16, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我以拉蒂夫家族的名义，正式和弗亚矿区所有常驻居民签订了具备约束力的官方合作协议。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [16]={next_id=17, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="往后矿区出产的所有星彩源晶，拉蒂夫家族会以正常市场价的价格统一收购。同时家族会派驻专员常驻此地，负责基础建设、医疗资源、教育设施的全方位扶持。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [17]={next_id=18, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……当然，这一切的前提是，矿区居民自愿合作……我们可不是来当第二个凯瑞公司的。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [18]={next_id=19, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你看向她，这个平日里小孩子气的拉蒂夫小小姐认真起来的样子还真有几分大人的气质。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [19]={next_id=20, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="别那样看我。我做这些也不全是为了他们。稳定的矿区对拉蒂夫家族的长远利益也有好处。互惠互利罢了。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [20]={next_id=21, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她别过脸，耳尖微微泛红。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [21]={next_id=22, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你忍不住笑了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [22]={next_id=23, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那就多谢了。替居民们谢谢你。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [23]={next_id=24, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="哼。你要谢的人可不止我一个。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [24]={next_id=25, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她朝聚居地中央扬了扬下巴。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [25]={next_id=26, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那位“余烬家主”这几天可没闲着。又是安置孤儿，又是调配物资，连居民吵架都要她去劝架……我看她比当黑帮老大的时候忙多了。", msg_color="", msg_size=0, talker="星钻", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [26]={next_id=27, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你顺着她的目光望去。蛰吻正蹲在一间木屋门口，手里端着一碗热汤，面前坐着米拉的母亲。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [27]={next_id=28, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的“晶肺”虽无法根治，但在蛰吻调配的药香调理下，已经好了许多。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_307.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3503", 0, 0, -2, 153}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
