   [235]={next_id=236, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的意思是？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT308_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4534", 0, 0, 28, 223},{ 3, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [236]={next_id=237, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="歌海娜直视着蛰吻，坦然道出早已想好的决定，字句清晰，坦荡直白。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4534", 0, 0, 28, 223},{ 3, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [237]={next_id=238, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我的意思很简单。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_ACT308_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4534", 0, 0, 28, 223},{ 3, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [238]={next_id=239, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她松开你的右臂，温柔的将你的脑袋抱进自己的怀里。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4534", 0, 0, 28, 223},{ 3, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
